// mv overwrites files, so delete any existing file.
if (destFile.exists()) {
    destFile.delete();
}
// mv by renaming the file.
boolean result = src.renameTo(destFile);
if (!result) {
    callback.invoke("mv failed for unknown reasons");
    return;
}

